import type { EngineInterface, PermissionRequestDecision, Register } from 'claude-code'

// maiTerm's link to the Claude Code session running in one of its tabs.
//
// maiTerm writes this folder into its data directory, and on an ssh host into
// ~/.maiterm/claude-mod, and names it in every tab's CLAUDE_CODE_PLUGIN_DIRS
// (claude_code/claude_mod.rs). It forwards the same hook events maiTerm's settings.json hooks
// send to POST /hooks, with two differences that are the point: every event names its tab
// (`tab_id=`), so nothing has to be inferred from a session id, and it says it came from here
// (`via=mod`), so the server drops the settings hooks' copy of each one. A Claude Code too old for mods never loads this, and its settings hooks
// run exactly as before.

// Tested against 2.1.295; the API is early access and may move between releases.
const MIN_VERSION = [2, 1, 290]

type Link = { tab: string; port: string; auth: string }

let link: Promise<Link | null> | undefined

function isAtLeast(version: string, min: number[]): boolean {
  const parts = version.split(/[.-]/).map(n => Number.parseInt(n, 10))
  for (let i = 0; i < min.length; i++) {
    const have = parts[i] ?? 0
    const want = min[i] ?? 0
    if (Number.isNaN(have) || have < want) return false
    if (have > want) return true
  }
  return true
}

async function load($: EngineInterface): Promise<Link | null> {
  const [tab, port, auth] = await Promise.all([
    $.env.get('MAITERM_TAB_ID'),
    $.env.get('MAITERM_PORT'),
    $.env.get('MAITERM_AUTH'),
  ])
  if (!tab || !port || !auth) return null
  const { version } = await $.session.version()
  if (!isAtLeast(version, MIN_VERSION)) return null
  // Tells maiTerm's SessionStart/SessionEnd command hooks, which run beneath this mod and
  // inherit this process's environment, that this mod speaks for the tab.
  await $.env.set('MAITERM_VIA_MOD', '1')
  return { tab, port, auth }
}

// Resolved once per module load. A load that fails is retried by the next event rather than
// leaving the tab unlinked for the rest of the session.
function linkOf($: EngineInterface): Promise<Link | null> {
  link ??= load($).catch(() => {
    link = undefined
    return null
  })
  return link
}

// POSTs one hook event; resolves the reply body, or undefined when maiTerm did not answer.
// Never rejects: a hook that throws would be skipped, and its event lost.
async function send($: EngineInterface, to: Link, event: unknown, query = ''): Promise<string | undefined> {
  try {
    const r = await $.http.fetch(
      `http://127.0.0.1:${to.port}/hooks?via=mod&tab_id=${encodeURIComponent(to.tab)}${query}`,
      {
        method: 'POST',
        headers: { 'x-claude-code-ide-authorization': to.auth, 'content-type': 'application/json' },
        body: JSON.stringify(event),
      },
    )
    return r.ok ? r.text : undefined
  } catch {
    return undefined
  }
}

// --- Answers from maiTerm (claude_code/mod_asks.rs) ---------------------------------------
//
// A permission dialog or an AskUserQuestion selector can be answered from maiTerm (the phone,
// the Loom, the Overlord) as well as at the desktop. The hook behind it registers an ask with
// the event it sends, then waits on GET /hooks/ask in short rounds: one fetch dies at about 30 s,
// and a round this short also lets maiTerm tell a waiting hook from a gone one. A key pressed at
// the desktop still wins; Claude then abandons the hook, which aborts its fetch.

let askSeq = 0

function newAskId(): string {
  askSeq += 1
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}-${askSeq}`
}

// Resolves maiTerm's answer once it gives one, or undefined when maiTerm stops holding the ask
// or can't be reached. `isDone` ends the wait between rounds once the prompt is settled.
async function awaitAnswer($: EngineInterface, to: Link, ask: string, isDone: () => boolean): Promise<unknown> {
  const url = `http://127.0.0.1:${to.port}/hooks/ask?id=${encodeURIComponent(ask)}&wait=10`
  while (!isDone()) {
    let r
    try {
      r = await $.http.fetch(url, { headers: { 'x-claude-code-ide-authorization': to.auth } })
    } catch {
      return undefined
    }
    if (r.status === 204) continue
    if (r.status !== 200) return undefined
    try {
      return JSON.parse(r.text)
    } catch {
      return undefined
    }
  }
  return undefined
}

async function cancelAsk($: EngineInterface, to: Link, ask: string): Promise<void> {
  try {
    await $.http.fetch(`http://127.0.0.1:${to.port}/hooks/ask?id=${encodeURIComponent(ask)}&cancel=1`, {
      headers: { 'x-claude-code-ide-authorization': to.auth },
    })
  } catch {
    // Unanswered, the ask is pruned once nothing polls it.
  }
}

// --- Prompts from maiTerm (claude_code/mod_inbox.rs) --------------------------------------
//
// What maiTerm sends this tab's agent between turns (a phone message, a follow-up, an Overlord
// directive, a peer's message) comes through here rather than typed: one loop long-polls GET
// /hooks/inbox, acks each prompt (maiTerm refuses the ack for one it has meanwhile given up on
// and typed instead) and submits it, which starts a turn and leaves the human's draft in the
// box. Only in an interactive session: a `claude -p` an agent runs inherits this
// tab's environment, and must not take its prompts.

// The interactive session's id, kept in the environment because module state isn't: a module
// reloaded mid-session (maiTerm rewrites these files on upgrade) gets no `session.start`, and
// restarts its loop from the next event once this names the session it belongs to. A child
// process inherits the variable but runs another session. (`$.env` takes the name spelled out
// at each call: MAITERM_MOD_SESSION.)

let inboxRunning = false

function startInbox($: EngineInterface, to: Link): void {
  if (inboxRunning) return
  inboxRunning = true
  const base = `http://127.0.0.1:${to.port}/hooks/inbox?tab_id=${encodeURIComponent(to.tab)}`
  const headers = { 'x-claude-code-ide-authorization': to.auth }
  const again = (ms: number) => {
    $.clock.after(ms, () => {
      void round()
    })
  }
  const round = async (): Promise<void> => {
    let r
    try {
      r = await $.http.fetch(`${base}&wait=10`, { headers })
    } catch {
      return again(5000)
    }
    if (r.status === 204) return again(1)
    if (r.status !== 200) return again(5000)
    let offer: { id?: string; text?: string }
    try {
      offer = JSON.parse(r.text)
    } catch {
      return again(1)
    }
    if (offer.id && typeof offer.text === 'string') {
      try {
        const id = offer.id
        const ack = await $.http.fetch(`${base}&ack=${encodeURIComponent(id)}`, { headers })
        // Not awaited: it resolves only as the turn starts, and the next prompt shouldn't wait.
        // maiTerm sends only between turns, but one can start first; until this one's turn has,
        // it routes the tab's later prompts here too, so a typed one can't overtake it.
        if (ack.status === 204) {
          void $.prompt
            .submit({ text: offer.text, asUser: true })
            .catch(() => {})
            .then(() => $.http.fetch(`${base}&started=${encodeURIComponent(id)}`, { headers }))
            .catch(() => {})
        }
      } catch {
        // Unacked, maiTerm takes it back.
      }
    }
    again(1)
  }
  again(1)
}

async function ensureInbox($: EngineInterface, to: Link): Promise<void> {
  if (inboxRunning) return
  const [mine, session] = await Promise.all([$.env.get('MAITERM_MOD_SESSION'), $.session.id()])
  if (mine && mine === session) startInbox($, to)
}

// --- Transcript growth, for an ssh host (mailink/mirror.rs) --------------------------------
//
// On an ssh host maiTerm reads this session's transcript from a local copy it tops up over the
// connection, on each hook event — and a long turn sends none until it ends. So the rows the
// session stores are reported, and maiTerm fetches what was added. Not at once: a stored row
// reaches the file a beat later (seen on nova, 2.1.295: rows stored at :41–:43, the file grew
// at :44, so a report at :43 fetched nothing and the turn's text waited 15 s for the next hook).
// A burst is reported ~1 s after its first row, and again 3 s after that for a slower write. A
// local tab's transcript is read in place: maiTerm answers 410 and no more are sent.

let appendReports: 'idle' | 'pending' | 'off' = 'idle'
// Only the first answer can turn the reports off. A local tab says 410 from the start; an ssh tab
// can be told 410 for a few seconds while its tunnel reconnects (maiTerm re-lists the host's
// tabs one at a time), and stopping then would end the reports for this whole process.
let appendAnswered = false

async function reportAppended($: EngineInterface, to: Link): Promise<void> {
  try {
    const session = await $.session.id()
    const r = await $.http.fetch(
      `http://127.0.0.1:${to.port}/hooks/appended?tab_id=${encodeURIComponent(to.tab)}&session_id=${encodeURIComponent(session)}`,
      { headers: { 'x-claude-code-ide-authorization': to.auth } },
    )
    appendReports = r.status === 410 && !appendAnswered ? 'off' : 'idle'
    appendAnswered = true
  } catch {
    appendReports = 'idle'
  }
}

// The events maiTerm's server reads, forwarded as the settings hooks would have sent them.
// Sent BEFORE `next(e)`: the settings hooks run beneath, so maiTerm hears this copy first
// and knows to drop theirs.
async function relay<E, R>($: EngineInterface, e: E, next: (e: E) => Promise<R>): Promise<R> {
  const to = await linkOf($)
  if (to) {
    await send($, to, e)
    await ensureInbox($, to)
  }
  return next(e)
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const result = await next(e)
    const to = await linkOf($)
    if (!to) return result
    await $.env.set('MAITERM_MOD_SESSION', e.isInteractive ? await $.session.id() : '')
    if (e.isInteractive) startInbox($, to)
    return result
  })

  on('classic.SessionStart', async ($, e, next) => {
    const to = await linkOf($)
    if (!to) return next(e)
    // A /clear starts a new session in this process (and no `session.start`): the loop runs on.
    if (inboxRunning) await $.env.set('MAITERM_MOD_SESSION', e.session_id)
    // The server's reply is the session's standing instructions: the tab and session ids and
    // whatever this tab's features need (the Overlord, tasks, the stack, follow-ups).
    const priming = await send($, to, e, '&prime=1')
    const result = await next(e)
    if (!priming) return result
    return { ...result, additionalContext: [...(result.additionalContext ?? []), priming] }
  })

  on('classic.SessionEnd', relay)
  on('classic.Notification', relay)
  on('classic.Stop', relay)
  on('classic.UserPromptSubmit', relay)
  on('classic.PostToolUse', relay)
  on('classic.PostToolUseFailure', relay)
  // Runs while the dialog is on screen (Claude draws it and raises this together). The decision
  // maiTerm hands back closes the dialog as if its row had been pressed.
  on('classic.PermissionRequest', async ($, e, next) => {
    const to = await linkOf($)
    if (!to) return next(e)
    // AskUserQuestion's own permission is the selector itself, answered through tool.call below.
    if (e.tool_name === 'AskUserQuestion') return relay($, e, next)
    const ask = newAskId()
    await send($, to, e, `&ask=${encodeURIComponent(ask)}`)
    const result = await next(e)
    // A settings hook of the user's own already decided: that stands.
    if (result.decision) return result
    const answer = (await awaitAnswer($, to, ask, () => false)) as { decision?: PermissionRequestDecision } | undefined
    const decision = answer?.decision
    if (!decision) return result
    if (decision.behavior === 'deny' && decision.interrupt && !e.agent_id) {
      // A deny fires no hook, and an interrupted turn sends no Stop, so maiTerm would leave the
      // tab waiting on a dialog that is gone. The turn has stopped and the agent waits on its
      // human, which is what idle_prompt tells maiTerm; sent once the dialog has closed. Only
      // for the main thread's own dialog: a subagent's deny says nothing about whether the
      // main thread is still working, and idle_prompt would release its calls too.
      const session_id = e.session_id
      const cwd = e.cwd
      $.clock.after(300, () => {
        void send($, to, { hook_event_name: 'Notification', notification_type: 'idle_prompt', session_id, cwd })
      })
    }
    return { ...result, decision }
  })
  on('classic.SubagentStop', relay)
  on('classic.PreCompact', relay)

  // After the row is stored, never ahead of it: this hook sits in the store path. A subagent's
  // rows go to its own file, which maiTerm doesn't copy.
  on('session.append', async ($, e, next) => {
    const stored = await next(e)
    if (appendReports !== 'idle' || e.agentId) return stored
    const to = await linkOf($)
    if (to) {
      appendReports = 'pending'
      // Rows stored meanwhile ride along with this burst's reports.
      $.clock.after(1000, () => {
        void reportAppended($, to).then(() => {
          if (appendReports === 'off') return
          $.clock.after(3000, () => {
            if (appendReports === 'idle') void reportAppended($, to)
          })
        })
      })
    }
    return stored
  })

  // The one event whose reply matters: maiTerm allows a model switch it asked for, which
  // skips Claude's "Switch model?" cache-miss confirm.
  on('classic.PreModelSwitch', async ($, e, next) => {
    const to = await linkOf($)
    if (!to) return next(e)
    const reply = await send($, to, e)
    const result = await next(e)
    try {
      const decision = reply ? JSON.parse(reply)?.hookSpecificOutput : undefined
      if (decision?.permissionDecision === 'allow') {
        return { ...result, permissionDecision: 'allow', permissionDecisionReason: decision.permissionDecisionReason }
      }
    } catch {
      // An empty or non-JSON reply decides nothing.
    }
    return result
  })

  // PreToolUse comes from `tool.call` rather than `classic.PreToolUse`, whose input is the bare
  // tool call: it lacks the session id and, in a subagent, the agent's id, both of which the
  // permission ledger keys on (claude_code/gate.rs). This is the same moment, one level up.
  on('tool.call', async ($, e, next) => {
    const to = await linkOf($)
    if (!to) return next(e)
    const { tool, tool_use_id, agentId, consent: _consent, ...tool_input } = e as Record<string, unknown>
    const isQuestion = e.tool === 'AskUserQuestion'
    const ask = isQuestion ? newAskId() : undefined
    const call = {
      session_id: await $.session.id(),
      cwd: await $.session.cwd(),
      tool_name: tool,
      tool_input,
      tool_use_id,
      ...(agentId ? { agent_id: agentId } : {}),
    }
    await send($, to, { hook_event_name: 'PreToolUse', ...call }, ask ? `&ask=${encodeURIComponent(ask)}` : '')
    if (!ask || e.tool !== 'AskUserQuestion') return next(e)

    // The selector (`next`) and maiTerm race; whichever answers first is the tool's result.
    type First =
      | { from: 'desktop'; r: Awaited<ReturnType<typeof next>> }
      | { from: 'maiterm'; answers: Record<string, string> }
    let settled = false
    const local: Promise<First> = next(e).then(r => {
      settled = true
      return { from: 'desktop', r }
    })
    const remote: Promise<First> = awaitAnswer($, to, ask, () => settled).then(a => {
      const answers = (a as { answers?: Record<string, string> } | undefined)?.answers
      // Nothing from maiTerm: the desktop's answer is the only one coming.
      return answers ? { from: 'maiterm', answers } : local
    })
    const first = await Promise.race([local, remote])
    if (first.from === 'desktop') {
      void cancelAsk($, to, ask)
      return first.r
    }
    settled = true
    const answered = { questions: e.questions, answers: first.answers }
    // Answering with the selector still pending aborts what runs beneath, Claude's PostToolUse
    // for this call with it, and that event is what tells maiTerm the question is over: without
    // it the phone kept drawing an answered question until the turn ended. So its end is
    // reported here.
    await send($, to, { hook_event_name: 'PostToolUse', ...call, tool_response: answered })
    return { result: answered }
  })

  // An agent in a maiTerm tab talks to OTHER agents only where its human said it may: over the
  // mesh (sendToBridgedAgent), whose roster is the workspaces the human linked. Claude's own
  // SendMessage also reaches every other Claude session on the machine (ListAgents), which
  // bypassed that entirely — maiMarketing and maiSoft agents traded messages with no link
  // between their workspaces, unseen by maiTerm. So a send to ANOTHER SESSION is refused, and the
  // model reads the reason as the tool's result. A plugin sending on the tab's behalf is held to
  // the same rule: whoever composed it, it would still be this tab talking past its mesh.
  //
  // Refused only on positive evidence that the recipient is a session (`isOtherSession`), never
  // because it is missing from the session's own agents: that list forgets a finished subagent
  // that SendMessage can still resume, and never holds the lead a teammate answers as
  // `team-lead` (review of 76421ae0). A session this misses is still stopped where it lands —
  // `crossSessionInbound: refuse` on the receiving end.
  on('tool.call', { tool: 'ListAgents' }, async ($, e, next) => {
    const r = await next(e)
    if (await linkOf($)) recordSessions((r as { result?: unknown }).result)
    return r
  })
  on('session.send', async ($, e, next) => {
    if (!(await linkOf($)) || !isOtherSession(e.to) || (await isOwnAgent($, e.to))) return next(e)
    return {
      isDelivered: false,
      reason:
        `maiTerm: "${e.to}" is another Claude session, and messaging other sessions is off in maiTerm tabs — ` +
        'your human decides which agents talk to each other. To reach another agent use sendToBridgedAgent ' +
        '(listBridgedPeers shows who you can reach); if the one you need is not there, ask your human to link ' +
        'its workspace to yours. SendMessage still works for your own subagents.',
    }
  })
}

// Names ListAgents filed under another session (its own machine's, a cloud one, a Remote Control
// one) during this module's life. The listing is the only way a model learns a session's name, so
// a name it can address is a name this saw. Lost on a reload (a deploy rewrites the mod), when the
// model has to list again before it can name one — and the inbound setting covers the gap.
const sessionNames = new Set<string>()
const SESSION_KIND = /session|cloud|remote|peer/i

function recordSessions(result: unknown) {
  const sections = (result as { sections?: { kind?: unknown; rows?: { name?: unknown; ref?: unknown; id?: unknown }[] }[] } | undefined)?.sections
  if (!Array.isArray(sections)) return
  for (const s of sections) {
    if (typeof s.kind !== 'string' || !SESSION_KIND.test(s.kind) || /agent|teammate/i.test(s.kind)) continue
    for (const row of s.rows ?? []) {
      for (const v of [row.name, row.id]) if (typeof v === 'string' && v) sessionNames.add(v)
      if (typeof row.name === 'string' && typeof row.ref === 'string') sessionNames.add(`${row.name} [${row.ref}]`)
    }
  }
}

// An address SendMessage only gives a session — `uds:<socket>` and `bridge:<session id>`, the
// forms its schema documents for one — or a name ListAgents listed as a session.
function isOtherSession(to: string): boolean {
  if (/^(uds|bridge):/.test(to)) return true
  return sessionNames.has(to) || sessionNames.has(to.replace(/\s*\[[^\]]*\]$/, ''))
}

// Is `to` this session's own subagent or teammate (or, from inside one, its parent)? Checked
// first so an own agent that happens to share a listed session's name is still reached.
async function isOwnAgent($: EngineInterface, to: string): Promise<boolean> {
  if (to === 'main') return true
  const agents = await $.agent.list().catch(() => [])
  return agents.some(a =>
    a.id === to || a.name === to || a.teammateId === to || (!!a.teammateId && a.teammateId.split('@')[0] === to),
  )
}

